<?php
/**
 * <div id="function.array-filter" class="refentry"> <div class="refnamediv">  <h1 class="refname">array_filter</h1>  <p class="verinfo">(PHP 4 &gt;= 4.0.6, PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">array_filter</span> — <span class="dc-title">使用回调函数过滤数组的元素</span></p> </div> <div class="refsect1 description" id="refsect1-function.array-filter-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>array_filter</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$array</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span></span> <span class="parameter" style="color:#3A95FF">\$callback</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span> <span class="parameter" style="color:#3A95FF">\$mode</span><span class="initializer"> = 0</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">   遍历 <span class="parameter" style="color:#3A95FF">array</span> 数组中的每个值，并将每个值传递给 <span class="parameter" style="color:#3A95FF">callback</span> 回调函数。   如果 <span class="parameter" style="color:#3A95FF">callback</span> 回调函数返回 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.true">true</a></span></strong>，则将 <span class="parameter" style="color:#3A95FF">array</span> 数组中的当前值返回到结果 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> 数组中。  </p>  <p class="para">   返回结果 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> 数组的键名（下标）会维持不变，如果 <span class="parameter" style="color:#3A95FF">array</span> 参数是索引数组，返回的结果 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> 数组键名（下标）可能会不连续。   可以使用 <span class="function">{@link array_values()}</span> 函数对数组重新索引。  </p></div> <div class="refsect1 parameters" id="refsect1-function.array-filter-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">array</span></dt>     <dd>      <p class="para">       要遍历的数组      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>     <dd>      <p class="para">       使用的回调函数      </p>      <p class="para">       如果没有提供 <span class="parameter" style="color:#3A95FF">callback</span> 回调函数，将删除数组中 <span class="parameter" style="color:#3A95FF">array</span> 的所有“空”元素。       有关 PHP 如何判定“空”元素，请参阅 <span class="function">{@link empty()}</span> 。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">mode</span></dt>     <dd>      <p class="para">       决定哪些参数发送到 <span class="parameter" style="color:#3A95FF">callback</span> 回调的标志：       </p><ul class="itemizedlist">        <li class="listitem">         <span class="simpara"><strong><span><a href="https://php.net/manual/zh/array.constants.php#constant.array-filter-use-key">ARRAY_FILTER_USE_KEY</a></span></strong> - 将键名作为 <span class="parameter" style="color:#3A95FF">callback</span> 回调的唯一参数，而不是值</span>        </li>        <li class="listitem">         <span class="simpara"><strong><span><a href="https://php.net/manual/zh/array.constants.php#constant.array-filter-use-both">ARRAY_FILTER_USE_BOTH</a></span></strong> - 将值和键都作为参数传递给 <span class="parameter" style="color:#3A95FF">callback</span> 回调，而不是仅传递值</span>        </li>       </ul>       默认值为 <span class="literal">0</span> ，只传递值作为 <span class="parameter" style="color:#3A95FF">callback</span> 回调的唯一参数。           </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.array-filter-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   返回过滤后的数组。  </p> </div> <div class="refsect1 changelog" id="refsect1-function.array-filter-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>8.0.0</td>      <td>       <span class="parameter" style="color:#3A95FF">callback</span> 现在可为空（nullable）。      </td>     </tr>     <tr> <td>8.0.0</td> <td>  如果 <span class="parameter" style="color:#3A95FF">callback</span> 接受引用传递参数，该方法将会抛出  <strong><span><a href="https://php.net/manual/zh/errorfunc.constants.php#constant.e-warning">E_WARNING</a></span></strong>。 </td></tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-function.array-filter-examples">  <h3 class="title">示例</h3>  <p class="para">   </p><div class="example" id="example-1">    <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">array_filter()</strong></span> 示例</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">function </span><span style="color: #9876AA">odd</span><span style="color: #007700">(</span><span style="color: #9876AA">\$var</span><span style="color: #007700">)<br>{<br>    </span><span style="color: #FF8000">// 返回输入整数是否为奇数（单数）<br>    </span><span style="color: #007700">return </span><span style="color: #9876AA">\$var </span><span style="color: #007700">&amp; </span><span style="color: #9876AA">1</span><span style="color: #007700">;<br>}<br>function </span><span style="color: #9876AA">even</span><span style="color: #007700">(</span><span style="color: #9876AA">\$var</span><span style="color: #007700">)<br>{<br>    </span><span style="color: #FF8000">// 返回输入整数是否为偶数<br>    </span><span style="color: #007700">return !(</span><span style="color: #9876AA">\$var </span><span style="color: #007700">&amp; </span><span style="color: #9876AA">1</span><span style="color: #007700">);<br>}<br></span><span style="color: #9876AA">\$array1 </span><span style="color: #007700">= [</span><span style="color: #DD0000">'a' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'b' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'c' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #DD0000">'d' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #DD0000">'e' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">5</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$array2 </span><span style="color: #007700">= [</span><span style="color: #9876AA">6</span><span style="color: #007700">, </span><span style="color: #9876AA">7</span><span style="color: #007700">, </span><span style="color: #9876AA">8</span><span style="color: #007700">, </span><span style="color: #9876AA">9</span><span style="color: #007700">, </span><span style="color: #9876AA">10</span><span style="color: #007700">, </span><span style="color: #9876AA">11</span><span style="color: #007700">, </span><span style="color: #9876AA">12</span><span style="color: #007700">];<br>echo </span><span style="color: #DD0000">"Odd :\n"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_filter</span><span style="color: #007700">(</span><span style="color: #9876AA">\$array1</span><span style="color: #007700">, </span><span style="color: #DD0000">"odd"</span><span style="color: #007700">));<br>echo </span><span style="color: #DD0000">"Even:\n"</span><span style="color: #007700">;<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_filter</span><span style="color: #007700">(</span><span style="color: #9876AA">\$array2</span><span style="color: #007700">, </span><span style="color: #DD0000">"even"</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Odd&nbsp;:<br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[a]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[c]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;[e]&nbsp;=&gt;&nbsp;5<br>)<br>Even:<br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;6<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;8<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;10<br>&nbsp;&nbsp;&nbsp;&nbsp;[6]&nbsp;=&gt;&nbsp;12<br>)</blockquote></div>    </div>   </div>   <div class="example" id="example-2">    <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">array_filter()</strong></span> 不使用 <span class="parameter" style="color:#3A95FF">callback</span> 时</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$entry </span><span style="color: #007700">= [<br>    </span><span style="color: #9876AA">0 </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'foo'</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">1 </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">false</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">2 </span><span style="color: #007700">=&gt; -</span><span style="color: #9876AA">1</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">3 </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">null</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">4 </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">''</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">5 </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'0'</span><span style="color: #007700">,<br>    </span><span style="color: #9876AA">6 </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">0</span><span style="color: #007700">,<br>];<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_filter</span><span style="color: #007700">(</span><span style="color: #9876AA">\$entry</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;foo<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;-1<br>)</blockquote></div>    </div>   </div>   <div class="example" id="example-3">    <p><strong>示例 #3 <span class="function"><strong style="color:#CC7832">array_filter()</strong></span> 使用 <span class="parameter" style="color:#3A95FF">mode</span> 时</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$arr </span><span style="color: #007700">= [</span><span style="color: #DD0000">'a' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #DD0000">'b' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #DD0000">'c' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #DD0000">'d' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">4</span><span style="color: #007700">];<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_filter</span><span style="color: #007700">(</span><span style="color: #9876AA">\$arr</span><span style="color: #007700">, function(</span><span style="color: #9876AA">\$k</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$k </span><span style="color: #007700">== </span><span style="color: #DD0000">'b'</span><span style="color: #007700">;<br>}, </span><span style="color: #9876AA">ARRAY_FILTER_USE_KEY</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_filter</span><span style="color: #007700">(</span><span style="color: #9876AA">\$arr</span><span style="color: #007700">, function(</span><span style="color: #9876AA">\$v</span><span style="color: #007700">, </span><span style="color: #9876AA">\$k</span><span style="color: #007700">) {<br>    return </span><span style="color: #9876AA">\$k </span><span style="color: #007700">== </span><span style="color: #DD0000">'b' </span><span style="color: #007700">|| </span><span style="color: #9876AA">\$v </span><span style="color: #007700">== </span><span style="color: #9876AA">4</span><span style="color: #007700">;<br>}, </span><span style="color: #9876AA">ARRAY_FILTER_USE_BOTH</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;["b"]=&gt;<br>&nbsp;&nbsp;int(2)<br>}<br>array(2)&nbsp;{<br>&nbsp;&nbsp;["b"]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;["d"]=&gt;<br>&nbsp;&nbsp;int(4)<br>}</blockquote></div>    </div>   </div>   </div> <div class="refsect1 notes" id="refsect1-function.array-filter-notes">  <h3 class="title">注释</h3>  <div class="caution"><strong class="caution">警告</strong>   <p class="para">    不应该在回调函数中改变数组（如：添加或销毁“unset”当前数组和里面的元素），否则此函数的行为将不可预测。   </p>  </div> </div>  <div class="refsect1 seealso" id="refsect1-function.array-filter-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link array_intersect()} - 计算数组的交集</span></li>    <li><span class="function">{@link array_find()} - 返回满足回调函数条件的第一个元素</span></li>    <li><span class="function">{@link array_any()} - 检查数组中是否至少有一个元素满足回调函数的条件</span></li>    <li><span class="function">{@link array_map()} - 为数组的每个元素应用回调函数</span></li>    <li><span class="function">{@link array_reduce()} - 用回调函数迭代地将数组简化为单一的值</span></li>   </ul>   </div></div>
 * 
 * Some function.
 */
function array_filter(array $array): array {}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\array_filter(0), type(0));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertCount(1, $violations);
        $this->assertStringContainsString('array_filter', $violations[0]);
        $this->assertStringContainsString('no @meta phpdoc tag', $violations[0]);
    }


    public function testHandlesMethodsInClasses(): void
    {

        $stubCode = <<<'PHP'
<?php

class DOMNode {
    /**
     * @meta
     */
    public function appendChild(DOMNode $node) {}
}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\DOMNode::appendChild(0), type(0));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertEmpty($violations);
    }


    public function testDetectsMethodOverrideWithoutMetaTag(): void
    {

        $stubCode = <<<'PHP'
<?php

class DOMNode {
    /**
     * Adds child.
     */
    public function appendChild(DOMNode $node) {}
}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\DOMNode::appendChild(0), type(0));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertCount(1, $violations);
        $this->assertStringContainsString('DOMNode::appendChild', $violations[0]);
    }


    public function testSkipsThirdPartyOverrides(): void
    {

        $stubCode = <<<'PHP'
<?php

function some_func(): void {}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\PHPUnit\Framework\TestCase::createMock(0), map(['' => '$0']));
    override(\Mockery::mock(0), map(['' => '@']));
    override(\mock(0), map(['' => '@']));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertEmpty($violations);
    }


    public function testHandlesNamespacedClasses(): void
    {

        $stubCode = <<<'PHP'
<?php
namespace FFI {

    class FFI {
        /**
         * @meta
         */
        public static function addr($ptr) {}
    }
}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\FFI\FFI::addr(), type(0));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertEmpty($violations);
    }


    public function testBidirectionalMismatch(): void
    {

        $stubCode = <<<'PHP'
<?php
/**
 * @meta
 */
function func_with_meta(): array {}


function func_without_meta(): array {}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    override(\func_without_meta(0), type(0));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertCount(2, $violations);


        $violationTexts = implode("\n", $violations);
        $this->assertStringContainsString('func_with_meta', $violationTexts);
        $this->assertStringContainsString('func_without_meta', $violationTexts);
    }


    public function testSkipsKnownMetaTagWithoutOverride(): void
    {
        // array_map keeps a @meta tag but intentionally has no override() entry,
        // because its return type depends on the callback, not on an argument type.

        $stubCode = <<<'PHP'
<?php
/**
 * <div id="function.array-map" class="refentry">   <div class="refnamediv">    <h1 class="refname">array_map</h1>    <p class="verinfo">(PHP 4 &gt;= 4.0.6, PHP 5, PHP 7, PHP 8)</p><p class="refpurpose"><span class="refname">array_map</span> — <span class="dc-title">     为数组的每个元素应用回调函数    </span></p>   </div> <div class="refsect1 description" id="refsect1-function.array-map-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>array_map</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span></span> <span class="parameter" style="color:#3A95FF">\$callback</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">\$array</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span> <span class="parameter" style="color:#3A95FF">...\$arrays</span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="para rdfs-comment">   <span class="function"><strong style="color:#CC7832">array_map()</strong></span> 返回一个 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>，包含将 <span class="parameter" style="color:#3A95FF">array</span> 的相应值作为回调的参数顺序调用    <span class="parameter" style="color:#3A95FF">callback</span> 后的结果（如果提供了更多数组，还会利用 <span class="parameter" style="color:#3A95FF">arrays</span>    传入）。<span class="parameter" style="color:#3A95FF">callback</span> 函数形参的数量必须匹配 <span class="function"><strong style="color:#CC7832">array_map()</strong></span>    实参中数组的数量。多余的实参数组将会被忽略。如果提供的实参数组的数量不足，将抛出 <span class="classname"><a href="https://php.net/manual/zh/class.argumentcounterror.php" class="classname">ArgumentCountError</a></span>。  </p> </div>  <div class="refsect1 parameters" id="refsect1-function.array-map-parameters">  <h3 class="title">参数</h3>  <p class="para">   </p><dl>         <dt><span class="parameter" style="color:#3A95FF">callback</span></dt>     <dd>      <p class="para">       回调函数 <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.callable.php" class="type callable" style="color:#EAB766">callable</a></span>，应用到每个数组里的每个元素。      </p>      <p class="para">       多个数组操作合并时，<span class="parameter" style="color:#3A95FF">callback</span>       可以设置为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>，并且会返回数组，该数组的每个元素包含输入数组中内部数组指针相同位置的元素（见下面的示例）。如果只提供了       <span class="parameter" style="color:#3A95FF">array</span> 数组，<span class="methodname" style="color:#CC7832"><strong>array_map()</strong></span> 会返回输入的数组。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">array</span></dt>     <dd>      <p class="para">       数组，遍历运行 <span class="parameter" style="color:#3A95FF">callback</span> 函数。      </p>     </dd>             <dt><span class="parameter" style="color:#3A95FF">arrays</span></dt>     <dd>      <p class="para">       额外的数组列表，每个都遍历运行 <span class="parameter" style="color:#3A95FF">callback</span> 函数。      </p>     </dd>       </dl>   </div> <div class="refsect1 returnvalues" id="refsect1-function.array-map-returnvalues">  <h3 class="title">返回值</h3>  <p class="para">   返回数组，包含将 <span class="parameter" style="color:#3A95FF">array</span> 的相应值作为回调的参数调用 <span class="parameter" style="color:#3A95FF">callback</span>   函数后的结果（如果提供了更多数组，还会利用 <span class="parameter" style="color:#3A95FF">arrays</span> 传入）。  </p>  <p class="para">   当仅仅传入一个数组时，返回的数组会保留传入参数的键（key）。   传入多个数组时，返回的数组键是按顺序的 integer。  </p> </div> <div class="refsect1 changelog" id="refsect1-function.array-map-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr> <td>8.0.0</td> <td>  如果 <span class="parameter" style="color:#3A95FF">callback</span> 接受引用传递参数，该方法将会抛出  <strong><span><a href="https://php.net/manual/zh/errorfunc.constants.php#constant.e-warning">E_WARNING</a></span></strong>。 </td></tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-function.array-map-examples">  <h3 class="title">示例</h3>  <p class="para">     </p><div class="example" id="example-1">      <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">array_map()</strong></span> 示例</strong></p>      <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">function </span><span style="color: #9876AA">cube</span><span style="color: #007700">(</span><span style="color: #9876AA">\$n</span><span style="color: #007700">)<br>{<br>    return (</span><span style="color: #9876AA">\$n </span><span style="color: #007700">* </span><span style="color: #9876AA">\$n </span><span style="color: #007700">* </span><span style="color: #9876AA">\$n</span><span style="color: #007700">);<br>}<br><br></span><span style="color: #9876AA">\$a </span><span style="color: #007700">= [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= </span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #DD0000">'cube'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$a</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$b</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>      </div>      <div class="example-contents"><p>       这使得 <var class="varname">\$b</var> 成为：      </p></div>      <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;8<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;27<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;64<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;125<br>)</blockquote></div>      </div>     </div>    <p class="para">   </p><div class="example" id="example-2">    <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">array_map()</strong></span> 使用匿名函数</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$func </span><span style="color: #007700">= function(</span><span style="color: #9876AA">int \$value</span><span style="color: #007700">): </span><span style="color: #9876AA">int </span><span style="color: #007700">{<br>    return </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">;<br>};<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">\$func</span><span style="color: #007700">, </span><span style="color: #9876AA">range</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">)));<br><br></span><span style="color: #FF8000">// 或者从 PHP 7.4.0 起：<br><br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(fn(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">): </span><span style="color: #9876AA">int </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$value </span><span style="color: #007700">* </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">range</span><span style="color: #007700">(</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">)));<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;6<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;8<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;10<br>)</blockquote></div>    </div>   </div>    <p class="para">   </p><div class="example" id="example-3">    <p><strong>示例 #3 <span class="function"><strong style="color:#CC7832">array_map()</strong></span>：使用更多的数组</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">function </span><span style="color: #9876AA">show_Spanish</span><span style="color: #007700">(</span><span style="color: #9876AA">int \$n</span><span style="color: #007700">, </span><span style="color: #9876AA">string \$m</span><span style="color: #007700">): </span><span style="color: #9876AA">string<br></span><span style="color: #007700">{<br>    return </span><span style="color: #DD0000">"The number </span><span style="color: #007700">{</span><span style="color: #9876AA">\$n</span><span style="color: #007700">}</span><span style="color: #DD0000"> is called </span><span style="color: #007700">{</span><span style="color: #9876AA">\$m</span><span style="color: #007700">}</span><span style="color: #DD0000"> in Spanish"</span><span style="color: #007700">;<br>}<br><br>function </span><span style="color: #9876AA">map_Spanish</span><span style="color: #007700">(</span><span style="color: #9876AA">int \$n</span><span style="color: #007700">, </span><span style="color: #9876AA">string \$m</span><span style="color: #007700">): array<br>{<br>    return [</span><span style="color: #9876AA">\$n </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$m</span><span style="color: #007700">];<br>}<br><br></span><span style="color: #9876AA">\$a </span><span style="color: #007700">= [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= [</span><span style="color: #DD0000">'uno'</span><span style="color: #007700">, </span><span style="color: #DD0000">'dos'</span><span style="color: #007700">, </span><span style="color: #DD0000">'tres'</span><span style="color: #007700">, </span><span style="color: #DD0000">'cuatro'</span><span style="color: #007700">, </span><span style="color: #DD0000">'cinco'</span><span style="color: #007700">];<br><br></span><span style="color: #9876AA">\$c </span><span style="color: #007700">= </span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #DD0000">'show_Spanish'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$c</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$d </span><span style="color: #007700">= </span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #DD0000">'map_Spanish'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$a </span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$d</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">//&nbsp;打印&nbsp;\$c<br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;The&nbsp;number&nbsp;1&nbsp;is&nbsp;called&nbsp;uno&nbsp;in&nbsp;Spanish<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;The&nbsp;number&nbsp;2&nbsp;is&nbsp;called&nbsp;dos&nbsp;in&nbsp;Spanish<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;The&nbsp;number&nbsp;3&nbsp;is&nbsp;called&nbsp;tres&nbsp;in&nbsp;Spanish<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;The&nbsp;number&nbsp;4&nbsp;is&nbsp;called&nbsp;cuatro&nbsp;in&nbsp;Spanish<br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;The&nbsp;number&nbsp;5&nbsp;is&nbsp;called&nbsp;cinco&nbsp;in&nbsp;Spanish<br>)<br><br>//&nbsp;打印&nbsp;\$d<br>Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;uno<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;dos<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;tres<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;cuatro<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[5]&nbsp;=&gt;&nbsp;cinco<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>)</blockquote></div>    </div>   </div>    <p class="para">   传入两个及以上的数组时，它们元素数量将会相同。因为回调函数会并行地处理相互对应的元素。   如果几个数组的元素数量不一致：空元素会扩展短那个数组，直到长度和最长的数组一样。  </p>  <p class="para">   此函数有个有趣的用法：传入 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> 作为回调函数的名称，将创建多维数组（一个数组，内部包含数组。）  </p>  <p class="para">   </p><div class="example" id="example-4">    <p><strong>示例 #4 多个数组的合并操作</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$a </span><span style="color: #007700">= [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">, </span><span style="color: #9876AA">4</span><span style="color: #007700">, </span><span style="color: #9876AA">5</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$b </span><span style="color: #007700">= [</span><span style="color: #DD0000">'one'</span><span style="color: #007700">, </span><span style="color: #DD0000">'two'</span><span style="color: #007700">, </span><span style="color: #DD0000">'three'</span><span style="color: #007700">, </span><span style="color: #DD0000">'four'</span><span style="color: #007700">, </span><span style="color: #DD0000">'five'</span><span style="color: #007700">];<br></span><span style="color: #9876AA">\$c </span><span style="color: #007700">= [</span><span style="color: #DD0000">'uno'</span><span style="color: #007700">, </span><span style="color: #DD0000">'dos'</span><span style="color: #007700">, </span><span style="color: #DD0000">'tres'</span><span style="color: #007700">, </span><span style="color: #DD0000">'cuatro'</span><span style="color: #007700">, </span><span style="color: #DD0000">'cinco'</span><span style="color: #007700">];<br><br></span><span style="color: #9876AA">\$d </span><span style="color: #007700">= </span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, </span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">, </span><span style="color: #9876AA">\$c</span><span style="color: #007700">);<br></span><span style="color: #9876AA">print_r</span><span style="color: #007700">(</span><span style="color: #9876AA">\$d</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">Array<br>(<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;1<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;one<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;uno<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;2<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;two<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;dos<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;3<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;three<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;tres<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[3]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;4<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;four<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;cuatro<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>&nbsp;&nbsp;&nbsp;&nbsp;[4]&nbsp;=&gt;&nbsp;Array<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[0]&nbsp;=&gt;&nbsp;5<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[1]&nbsp;=&gt;&nbsp;five<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;[2]&nbsp;=&gt;&nbsp;cinco<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;)<br><br>)</blockquote></div>    </div>   </div>      <p class="para">   </p><div class="example" id="example-5">    <p><strong>示例 #5      仅有 <span class="parameter" style="color:#3A95FF">array1</span> 时，<span class="parameter" style="color:#3A95FF">callback</span> 设置为 <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong>    </strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$array </span><span style="color: #007700">= [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">];<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, </span><span style="color: #9876AA">\$array</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;int(3)<br>}</blockquote></div>    </div>   </div>    <p class="para">   </p><div class="example" id="example-6">    <p><strong>示例 #6 <span class="function"><strong style="color:#CC7832">array_map()</strong></span> 键（key）是 string</strong></p>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$arr </span><span style="color: #007700">= array(</span><span style="color: #DD0000">"stringkey" </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"value"</span><span style="color: #007700">);<br>function </span><span style="color: #9876AA">cb1</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">) {<br>    return [</span><span style="color: #9876AA">\$a</span><span style="color: #007700">];<br>}<br>function </span><span style="color: #9876AA">cb2</span><span style="color: #007700">(</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">) {<br>    return [</span><span style="color: #9876AA">\$a</span><span style="color: #007700">, </span><span style="color: #9876AA">\$b</span><span style="color: #007700">];<br>}<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #DD0000">'cb1'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #DD0000">'cb2'</span><span style="color: #007700">, </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">, </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">,  </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">));<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">null</span><span style="color: #007700">, </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">, </span><span style="color: #9876AA">\$arr</span><span style="color: #007700">));<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">array(1)&nbsp;{<br>&nbsp;&nbsp;["stringkey"]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(5)&nbsp;"value"<br>&nbsp;&nbsp;}<br>}<br>array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(5)&nbsp;"value"<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(5)&nbsp;"value"<br>&nbsp;&nbsp;}<br>}<br>array(1)&nbsp;{<br>&nbsp;&nbsp;["stringkey"]=&gt;<br>&nbsp;&nbsp;string(5)&nbsp;"value"<br>}<br>array(1)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;array(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(5)&nbsp;"value"<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(5)&nbsp;"value"<br>&nbsp;&nbsp;}<br>}</blockquote></div>    </div>   </div>   <div class="example" id="example-7">    <p><strong>示例 #7 <span class="function"><strong style="color:#CC7832">array_map()</strong></span> - 关联数组</strong></p>    <div class="example-contents"><p>     虽然 <span class="function"><strong style="color:#CC7832">array_map()</strong></span> 不能直接支持使用数组的键（key）作为输入，但可以使用     <span class="function">{@link array_keys()}</span> 进行模拟。    </p></div>    <div class="example-contents"><div class="annotation-interactive phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br>\$arr </span><span style="color: #007700">= [<br>    </span><span style="color: #DD0000">'v1' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'First release'</span><span style="color: #007700">,<br>    </span><span style="color: #DD0000">'v2' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Second release'</span><span style="color: #007700">,<br>    </span><span style="color: #DD0000">'v3' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'Third release'</span><span style="color: #007700">,<br>];<br><br></span><span style="color: #FF8000">// 注意： 在 7.4.0 之前，使用较长的语法来代替匿名函数。<br></span><span style="color: #9876AA">\$callback </span><span style="color: #007700">= fn(</span><span style="color: #9876AA">string \$k</span><span style="color: #007700">, </span><span style="color: #9876AA">string \$v</span><span style="color: #007700">): </span><span style="color: #9876AA">string </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"</span><span style="color: #9876AA">\$k</span><span style="color: #DD0000"> was the </span><span style="color: #9876AA">\$v</span><span style="color: #DD0000">"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">\$result </span><span style="color: #007700">= </span><span style="color: #9876AA">array_map</span><span style="color: #007700">(</span><span style="color: #9876AA">\$callback</span><span style="color: #007700">, </span><span style="color: #9876AA">array_keys</span><span style="color: #007700">(</span><span style="color: #9876AA">\$arr</span><span style="color: #007700">), </span><span style="color: #9876AA">array_values</span><span style="color: #007700">(</span><span style="color: #9876AA">\$arr</span><span style="color: #007700">));<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$result</span><span style="color: #007700">);<br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>    <div class="example-contents"><p>以上示例会输出：</p></div>    <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="annotation-interactive examplescode"><blockquote style="border:1px gray solid;">array(3)&nbsp;{<br>&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"v1&nbsp;was&nbsp;the&nbsp;First&nbsp;release"<br>&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;string(25)&nbsp;"v2&nbsp;was&nbsp;the&nbsp;Second&nbsp;release"<br>&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;string(24)&nbsp;"v3&nbsp;was&nbsp;the&nbsp;Third&nbsp;release"<br>}</blockquote></div>    </div>   </div>   </div> <div class="refsect1 seealso" id="refsect1-function.array-map-seealso">  <h3 class="title">参见</h3>  <p class="para">   </p><ul class="simplelist">    <li><span class="function">{@link array_filter()} - 使用回调函数过滤数组的元素</span></li>    <li><span class="function">{@link array_reduce()} - 用回调函数迭代地将数组简化为单一的值</span></li>    <li><span class="function">{@link array_walk()} - 使用用户自定义函数对数组中的每个元素做回调处理</span></li>   </ul>   </div></div>
 * 
 * @meta
 */
function array_map(?callable $callback, array $array): array {}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    //override(\array_map(0), type(1));
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertEmpty($violations);
    }


    public function testIgnoresFunctionsWithoutDocblock(): void
    {

        $stubCode = <<<'PHP'
<?php

function no_doc_func(): void {}
PHP;


        $metaCode = <<<'PHP'
<?php
namespace PHPSTORM_META {
    expectedArguments(\no_doc_func(), 0, 'a', 'b');
}
PHP;

        $violations = $this->checkWithFiles($stubCode, $metaCode);
        $this->assertEmpty($violations);
    }

    // --- Helper ---


    private function checkWithFiles(string $stubCode, string $metaCode): array
    {

        $dir = sys_get_temp_dir() . '/meta_internal_tag_test_' . getmypid();
        if (!is_dir($dir)) {
            mkdir($dir, 0777, true);
        }

        // Write stub file
        file_put_contents($dir . '/stubs.php', $stubCode);

        // Write meta file
        file_put_contents($dir . '/.phpstorm.meta.php', $metaCode);


        $violations = $this->check->check($dir);

        // Cleanup
        @unlink($dir . '/stubs.php');
        @unlink($dir . '/.phpstorm.meta.php');
        @rmdir($dir);

        return $violations;
    }
}
